# Minimal safe Markdown renderer for owned RFC sources; raw HTML is always escaped.
def markdown(s):
 out=[];paragraph=[];list_kind=None
 def inline(text):
  escaped=html.escape(text)
  escaped=re.sub(r'\[([^\]]+)\]\((https://[^\s)]+)\)',r'<a href="\2">\1</a>',escaped)
  escaped=re.sub(r'`([^`]+)`',r'<code>\1</code>',escaped)
  return re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',escaped)
 def flush():
  if paragraph:out.append('<p>'+inline(' '.join(paragraph))+'</p>');paragraph.clear()
 def close_list():
  nonlocal list_kind
  if list_kind:out.append('</'+list_kind+'>');list_kind=None
 for line in s.splitlines():
  if line.startswith('# '):continue
  if line.startswith('## '):flush();close_list();out.append('<h2>'+inline(line[3:])+'</h2>')
  elif line.startswith('### '):flush();close_list();out.append('<h3>'+inline(line[4:])+'</h3>')
  elif line.startswith('- ') or re.match(r'^\d+\. ',line):
   flush();kind='ul' if line.startswith('- ') else 'ol'
   if list_kind!=kind:close_list();list_kind=kind;out.append('<'+kind+'>')
   out.append('<li>'+inline(re.sub(r'^(?:- |\d+\. )','',line))+'</li>')
  elif not line.strip():flush();close_list()
  else:close_list();paragraph.append(line)
 flush();close_list();return ''.join(out)
def native_device_diagram():
 return '''<section class="section native-device"><h2>От модели до кабеля</h2><p>Целевая архитектура строгого узла. Схема объясняет проект; отчёт об испытании должен отдельно подтвердить каждый этап.</p><svg viewBox="0 0 1160 285" role="img" aria-labelledby="native-device-title native-device-desc"><title id="native-device-title">Локальная модель передаёт задачу IPvX-службе, которая отправляет Ethernet-кадр через сетевую карту маршрутизатору</title><desc id="native-device-desc">Внутри узла: модель, Unix-сокет, IPvX-служба, AF_PACKET и обычная сетевая карта. Ядро целевого образа без INET и IPv6. Снаружи: Ethernet-кабель и следующий маршрутизатор.</desc><defs><marker id="native-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0L7 3.5L0 7" fill="currentColor"/></marker></defs><rect class="native-machine" x="10" y="40" width="825" height="195"/><text class="native-caption" x="30" y="72">Узел агента · локальная ОС</text><g class="native-edge" marker-end="url(#native-arrow)"><path d="M158 138H178"/><path d="M306 138H326"/><path d="M454 138H474"/><path d="M622 138H642"/><path d="M792 138H958"/></g><g><rect x="30" y="98" width="128" height="80"/><text x="46" y="130">Модель</text><text class="native-small" x="46" y="154">локально</text></g><g><rect x="178" y="98" width="128" height="80"/><text x="194" y="130">Unix-сокет</text><text class="native-small" x="194" y="154">внутри узла</text></g><g><rect x="326" y="98" width="128" height="80"/><text x="342" y="130">IPvX-служба</text><text class="native-small" x="342" y="154">ID и пакет</text></g><g><rect x="474" y="98" width="148" height="80"/><text x="490" y="130">AF_PACKET</text><text class="native-small" x="490" y="154">без TCP/IP</text></g><g><rect x="642" y="98" width="150" height="80"/><text x="658" y="130">Сетевая карта</text><text class="native-small" x="658" y="154">обычный NIC</text></g><text class="native-small" x="845" y="111">кабель</text><text class="native-small" x="845" y="169">Ethernet</text><g><rect x="958" y="98" width="190" height="80"/><text x="974" y="130">Маршрутизатор R</text><text class="native-small" x="974" y="154">следующий переход</text></g><text class="native-small" x="30" y="212">CONFIG_INET выключен · CONFIG_IPV6 выключен · ключи создаются локально</text><text class="native-small" x="30" y="268">Физический канал остаётся Ethernet. Собственный IPvX определяет обмен поверх этого канала.</text></svg><ol class="native-device-mobile"><li><strong>Локальная модель</strong><span>Вычисляет задачу на своей машине.</span></li><li><strong>Unix-сокет</strong><span>Связывает модель и службу внутри одной ОС, без TCP.</span></li><li><strong>IPvX-служба</strong><span>Работает с ID, сообщениями и маршрутами.</span></li><li><strong>AF_PACKET</strong><span>Передаёт кадр при выключенных INET и IPv6 в ядре.</span></li><li><strong>Обычная сетевая карта</strong><span>Выводит кадр в Ethernet-кабель.</span></li><li><strong>Маршрутизатор R</strong><span>Принимает кадр и выбирает следующего соседа.</span></li></ol><p class="small">Сборочная машина, внешний операторский пульт и публичный портал могут использовать IP. В строгом образе управление, загрузка зависимостей и вызов модели не должны скрыто возвращаться к IP.</p></section>'''

def community_discussion(rfc):
 return f'''<section class="section community-discussion" data-community-rfc="{rfc}" id="discussion"><h2>Обсуждение RFC</h2><p>Опубликованные комментарии доступны всем. Новое сообщение сначала видят его автор и модераторы. Консультативный опрос предложений не принимает RFC и не заменяет голосование по <a href="rfc-0003.html">правилам проекта</a>.</p><p class="community-session-status" role="status" aria-live="polite">Проверяем возможность участия…</p><p class="community-sign-in" hidden><a href="https://ipvx.org/account.html">Войти через Relcom ID</a>, чтобы отправить комментарий или предложение.</p><form class="community-submit" hidden><label for="entry-kind">Тип сообщения</label><select id="entry-kind" name="kind"><option value="comment">Комментарий</option><option value="proposal">Предложение изменения</option></select><label for="entry-title">Заголовок <span class="small">обязателен для предложения</span></label><input id="entry-title" name="title" maxlength="200"><label for="entry-text">Текст</label><textarea id="entry-text" name="text" rows="6" maxlength="8000" required></textarea><p class="small">Не включайте пароли, ключи и закрытые данные. Укажите пункт RFC, причину изменения и способ проверки. Публикация требует модерации.</p><button class="button" type="submit">Отправить на модерацию</button><p class="community-submit-status" role="status" aria-live="polite"></p></form><div class="community-tabs" role="group" aria-label="Тип опубликованных сообщений"><button type="button" data-entry-kind="comment" aria-pressed="true">Комментарии</button><button type="button" data-entry-kind="proposal" aria-pressed="false">Предложения</button></div><div class="community-public" aria-live="polite"><p>Загружаем опубликованное обсуждение…</p></div><button class="button secondary community-public-more" type="button" hidden>Показать ещё</button><button class="button secondary community-public-retry" type="button" hidden>Повторить загрузку обсуждения</button><details class="community-own" hidden><summary>Мои сообщения и статус модерации</summary><div class="community-own-list"></div><button class="button secondary community-own-more" type="button" hidden>Показать ещё моих сообщений</button></details><noscript><p>Для обсуждения на портале нужен JavaScript. <a href="{REPO}/issues/new?template=proposal.yml">Подготовить предложение в GitHub</a> можно отдельно.</p></noscript><p class="small"><a href="{REPO}/issues/new?template=proposal.yml">Предложение в GitHub</a> остаётся отдельным путём к проверяемому изменению исходного текста.</p></section>'''

def strict_native_measurement():
 evidence=ROOT/'data/strict-native-2026-10-27/summary.json'
 if not evidence.exists():return ''
 measured=json.loads(evidence.read_text())
 if measured.get('status')!='measured':return ''
 return '''<section class="section" id="strict-measured"><h2>Проверено: три ОС без IP</h2><p><span class="badge pass">Измерено · 27 октября 2026</span></p><p class="lead">Три настоящих гостя Linux A → R → B загрузились с ядром без INET и IPv6. Задания и результаты прошли в собственных Ethernet-кадрах через посредника.</p><ul><li><strong>16 из 16 задач SHA-256 по 1 КиБ</strong> завершились с проверенным результатом. Все 90 кадров двух каналов проверены; EtherType только 0x88B5.</li><li><strong>12 отказов создания IP-сокетов в каждом сценарии:</strong> IPv4/IPv6, потоковые и дейтаграммные сокеты на каждой из трёх ОС. AF_PACKET и AF_UNIX доступны.</li><li><strong>После остановки единственного R — 0 из 16 задач.</strong> В отрицательном прогоне проверены все 10 кадров. В проверенном образе и каналах резервный IP-путь не обнаружен.</li></ul><p><strong>Модель через Unix-сокет на схеме пока остаётся целью.</strong> Этот прогон выполнял детерминированное вычисление SHA-256; модель в строгой ОС не запускалась. Наличие AF_UNIX проверено, библиотека взаимодействия с LLM этим опытом не подтверждена.</p><p>Три ВМ работали на одном CI-хосте. Переходы заданы заранее; ключи Ed25519 создаются в памяти и не сохраняются после перезагрузки. Доверие при первом контакте, без шифрования. Динамическое перестроение, физические устройства и эффективность относительно IP не проверялись. RFC остаётся черновиком.</p><p><a class="button" href="packet-replay.html">Посмотреть движение кадров</a></p><p><a href="downloads.html">Код, инструкции и захваты ZIP</a> · <a href="data/strict-native-2026-10-27/summary.json">Сводка и ограничения</a> · <a href="data/strict-native-2026-10-27/baseline/receipt.json">Квитанция 16/16</a> · <a href="data/strict-native-2026-10-27/relay-down/receipt.json">Отрицательный прогон</a> · <a href="https://github.com/relcom-technologies/ipvx-research/actions/runs/40500966557">Журнал настоящего запуска</a></p></section>'''

