history_path=ROOT/'history/events.jsonl'
if history_path.exists():
 participants=json.loads((ROOT/'history/participants.json').read_text())
 names={x['id']:x['display_name'] for x in participants['participants']}
 events=[json.loads(line) for line in history_path.read_text().splitlines() if line.strip()]
 status_names={'request':'Запрос','proposed':'Предложение','adopted':'Решение','implemented':'Реализовано','measured':'Измерено','failure':'Неудачная попытка','not_established':'Не доказано','in_progress':'В работе','explanatory':'Пояснение','review':'Рецензия','model_output':'Ответ модели','corrected':'Уточнение','superseded':'Пересмотрено'}
 h=heading('История проекта','Сохраняем предложения участников, изменения решений, неудачные попытки и результаты. Новые выводы дополняют предыдущие записи.')
 h+=article('Как читать эту историю','<p>У каждой записи есть автор высказывания или действия и тот, кто её зафиксировал. Начальная история восстановлена по доступной беседе и файлам; неизвестные даты не придуманы. Это журнал атрибуции, а не криптографическая проверка личности или голосование.</p><p><a href="history/events.jsonl">Скачать журнал JSONL</a> · <a href="history/participants.json">Участники и основания атрибуции</a> · <a href="history/history-ru.txt">Читать исходную хронологию</a> · <a href="data/downloads/ipvx-research-history.zip" download>Вся доступная история ZIP</a></p>')
 h+='<section class="prose history-list"><h2>Записи участников</h2><p>Сначала новые записи. Разверните событие, чтобы увидеть основание, источники и ограничения.</p>'
 for event in reversed(events):
  e=lambda key:html.escape(str(event.get(key,'')))
  actor=html.escape(names.get(event['attributed_to'],event['attributed_to']))
  recorder=html.escape(names.get(event['recorded_by'],event['recorded_by']))
  time=html.escape(event.get('occurred_at') or 'Дата события неизвестна')
  limits=''.join('<li>'+html.escape(x)+'</li>' for x in event.get('limitations',[]))
  sources=[]
  for source in event.get('evidence',[]):
   label=html.escape(source)
   if source.startswith(('https://github.com/relcom-technologies/','https://www.rfc-editor.org/','https://archive.org/','https://ipvx.org/')):
    sources.append('<li><a href="'+html.escape(source,quote=True)+'">'+label+'</a></li>')
   elif (ROOT/source).is_file():
    sources.append('<li><a href="'+REPO+'/blob/main/'+html.escape(source,quote=True)+'">'+label+'</a></li>')
   else:sources.append('<li>'+label+'</li>')
  h+='<details class="history-entry" id="'+e('id')+'"><summary>'+e('id')+' · '+e('title')+' <span class="badge">'+html.escape(status_names.get(event['status'],event['status']))+'</span></summary><p class="history-byline">'+actor+' · '+time+'</p><p>'+e('summary')+'</p><h3>Основание</h3><p>'+e('decision_rationale')+'</p>'
  if sources:h+='<h3>Источники и проверки</h3><ul>'+''.join(sources)+'</ul>'
  if limits:h+='<h3>Ограничения</h3><ul>'+limits+'</ul>'
  h+='<p class="small">Зафиксировал: '+recorder+'. '+('Авторская запись.' if event['origin']=='contemporaneous_author_record' else 'Восстановлено по доступным источникам.')+'</p></details>'
 h+='</section>'
 (ROOT/'history.html').write_text(layout('history.html','История проекта',h))

